#!/bin/sh
set -eu
SELF=$0
ROOT=$(CDPATH= cd -- "$(dirname -- "$SELF")" && pwd)
TMP=$(mktemp -d "${TMPDIR:-/tmp}/tetrio-patch-Linux-vO4.8217.XXXXXXXX")
trap 'rm -rf "$TMP"' EXIT HUP INT TERM
sed -n '/^# QP_PAYLOAD_BEGIN$/,/^# QP_PAYLOAD_END$/p' "$SELF" | sed '1d;$d;s/^# //' > "$TMP/payload.b64"
if base64 --help 2>&1 | grep -q -- '--decode'; then base64 --decode < "$TMP/payload.b64" > "$TMP/payload.zip"; else base64 -D < "$TMP/payload.b64" > "$TMP/payload.zip"; fi
if command -v shasum >/dev/null 2>&1; then GOT=$(shasum -a 256 "$TMP/payload.zip" | cut -d ' ' -f 1); else GOT=$(sha256sum "$TMP/payload.zip" | cut -d ' ' -f 1); fi
[ "$GOT" = "e65f47b9597b0f6833ed260c35916748ce3bbedd312e91190c38abedf91bf889" ] || { echo 'Payload SHA256 verification failed' >&2; exit 1; }
mkdir "$TMP/run"
if command -v unzip >/dev/null 2>&1; then unzip -q "$TMP/payload.zip" -d "$TMP/run"; elif command -v ditto >/dev/null 2>&1; then ditto -x -k "$TMP/payload.zip" "$TMP/run"; else echo 'unzip is required' >&2; exit 1; fi
RESOURCE_NAME='TETRIO-Resources-1.0.zip'
if [ -f "$ROOT/$RESOURCE_NAME" ]; then cp "$ROOT/$RESOURCE_NAME" "$TMP/run/$RESOURCE_NAME"; elif [ -f "$ROOT/../$RESOURCE_NAME" ]; then cp "$ROOT/../$RESOURCE_NAME" "$TMP/run/$RESOURCE_NAME"; elif [ -f "${HOME:-}/Downloads/$RESOURCE_NAME" ]; then cp "${HOME:-}/Downloads/$RESOURCE_NAME" "$TMP/run/$RESOURCE_NAME"; else echo "Missing $RESOURCE_NAME" >&2; exit 1; fi
export TETRIO_PATCH_RUNTIME_DIR="${TETRIO_PATCH_RUNTIME_DIR:-${XDG_CACHE_HOME:-${HOME:-/tmp}/.cache}/tetrio-patch-4.8217/runtime}"
export TETRIO_BUNDLE_DIR="$TMP/run"
cd "$TMP/run"
echo "tetrio-patch-Linux-vO4.8217"
/bin/sh ./start-unix.sh --kind O "$@"
